#!/usr/bin/env python3
"""Transcribe friend-branch utterance commits into an episode file.

Usage: transcribe.py <repo> <episode-file> <branch:name:sha> ...
"""
import subprocess
import sys
import re

repo = sys.argv[1]
epfile = sys.argv[2]
specs = sys.argv[3:]

def git(*args):
    return subprocess.run(["git", "-C", repo] + list(args),
                          capture_output=True, text=True, check=True).stdout

def meta(sha):
    out = git("show", "-s", "--format=%cI", sha).strip()
    return out

def body(sha):
    text = git("show", "-s", "--format=%B", sha)
    lines = text.split("\n")
    # find Reply-To line
    idx = None
    for i, l in enumerate(lines):
        if l.startswith("Reply-To:"):
            idx = i
            break
    if idx is None:
        raise SystemExit("no Reply-To in %s" % sha)
    # skip to blank line
    j = idx + 1
    while j < len(lines) and lines[j].strip() != "":
        j += 1
    j += 1
    body_lines = [l for l in lines[j:]]
    while body_lines and body_lines[-1].strip() == "":
        body_lines.pop()
    return "\n".join(body_lines)

def speaker(sha):
    out = git("show", "-s", "--format=%B", sha)
    for l in out.split("\n"):
        if l.startswith("Speaker:"):
            return l.split(":", 1)[1].strip()
    raise SystemExit("no Speaker in %s" % sha)

entries = []
for spec in specs:
    branch, sha = spec.split(":", 1)
    entries.append((meta(sha), sha, branch, speaker(sha), body(sha)))

entries.sort(key=lambda e: (e[0], e[1]))

with open(epfile, "a") as f:
    for t, sha, branch, spk, b in entries:
        f.write("\n\n**%s** (%s)\n\nSource: friend/%s @ %s\n\n%s\n" % (spk, t, branch, sha, b))

print("appended %d entries to %s" % (len(entries), epfile))
for e in entries:
    print(e[0], e[3], e[1][:12])

